public int minInsertions(String s) {
    int leftNeeded = 0; // Number of '(' needed to balance ')'
    int rightNeeded = 0; // Number of ')' needed to balance '('
    int balance = 0; // Current balance of '(' and ')'

    for (char ch : s.toCharArray()) {
        if (ch == '(') {
            // If there is a need for ')' to balance ')', can only be balanced by '('
            if (balance < 0) {
                rightNeeded += Math.abs(balance);
                balance = 0;
            }
            balance++;
        } else if (ch == ')') {
            balance--;
            // If balance is -1, it means there was an extra ')'
            if (balance == -1) {
                rightNeeded++;
                balance = 0; // Reset balance as we added a '(' virtually
            }
        }
    }

    // If balance > 0, there are extra '(' that need ')' to balance
    if (balance > 0) {
        leftNeeded = balance;
    }

    return leftNeeded + rightNeeded;
}

