public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be an array of three points, each with two integer coordinates.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the three points
    // Using the determinant method: 0.5 * | x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2) |
    // If the area is zero, the points are collinear and do not form a boomerang
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int factor2 = 2, factor3 = 3, factor5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(factor2, Math.min(factor3, factor5));
        uglyNumbers[i] = nextUgly;

        if (nextUgly == factor2) {
            index2++;
            factor2 = uglyNumbers[index2] * 2;
        }
        if (nextUgly == factor3) {
            index3++;
            factor3 = uglyNumbers[index3] * 3;
        }
        if (nextUgly == factor5) {
            index5++;
            factor5 = uglyNumbers[index5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            if (currentEnergy > maxEnergy) {
                maxEnergy = currentEnergy;
            }
            currentEnergy = 1;
        }
    }

    // Final check at the end of the loop
    if (currentEnergy > maxEnergy) {
        maxEnergy = currentEnergy;
    }

    return maxEnergy;
}

